package com.dawnrise.identity.notification.securityevent;
import com.dawnrise.identity.user.entity.User;import com.dawnrise.identity.user.repository.UserRepository;import org.junit.jupiter.api.Test;import org.springframework.context.ApplicationEventPublisher;import java.time.OffsetDateTime;import static org.mockito.Mockito.*;
class AccountLockoutNotificationAspectTest {@Test void persistsAndEmitsOnlyWhenThresholdAspectInvokesPersistence(){UserRepository users=mock(UserRepository.class);ApplicationEventPublisher events=mock(ApplicationEventPublisher.class);User user=mock(User.class);when(user.getOrganizationId()).thenReturn(4L);when(user.getId()).thenReturn(9L);when(user.getLockedUntil()).thenReturn(OffsetDateTime.parse("2026-10-30T10:00:00Z"));new AccountLockoutNotificationAspect.LockoutPersistence(users,events).persist(user);verify(users).saveAndFlush(user);verify(events).publishEvent((Object)argThat(e->e instanceof IdentitySecurityNotificationEvent event&&event.kind()==IdentitySecurityNotificationEvent.Kind.ACCOUNT_LOCKED&&event.userId()==9L));}}
